CREATE TABLE `membership_fee_schedules` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`fee_reference` varchar(40) NOT NULL,`membership_type_id` bigint unsigned NOT NULL,`amount` decimal(12,2) NOT NULL,`currency` char(3) NOT NULL DEFAULT 'ZAR',`billing_period` varchar(30) NOT NULL,`effective_from` date NOT NULL,`effective_to` date DEFAULT NULL,`active` tinyint(1) NOT NULL DEFAULT 1,`created_by` bigint unsigned NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `fee_schedules_reference_unique`(`fee_reference`),KEY `fee_schedules_lookup_index`(`membership_type_id`,`active`,`effective_from`,`effective_to`),CONSTRAINT `fee_schedules_type_foreign` FOREIGN KEY(`membership_type_id`) REFERENCES `membership_types`(`id`) ON DELETE RESTRICT,CONSTRAINT `fee_schedules_creator_foreign` FOREIGN KEY(`created_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `fee_schedules_amount_check` CHECK (`amount` >= 0),CONSTRAINT `fee_schedules_dates_check` CHECK (`effective_to` IS NULL OR `effective_to` >= `effective_from`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `memberships` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`membership_number` varchar(40) NOT NULL,`user_id` bigint unsigned NOT NULL,`membership_application_id` bigint unsigned NOT NULL,`membership_type_id` bigint unsigned NOT NULL,`status` varchar(40) NOT NULL,`starts_at` date DEFAULT NULL,`expires_at` date DEFAULT NULL,`activated_at` timestamp NULL DEFAULT NULL,`suspended_at` timestamp NULL DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `memberships_number_unique`(`membership_number`),UNIQUE KEY `memberships_application_unique`(`membership_application_id`),KEY `memberships_user_status_index`(`user_id`,`status`),KEY `memberships_type_status_index`(`membership_type_id`,`status`),CONSTRAINT `memberships_user_foreign` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `memberships_application_foreign` FOREIGN KEY(`membership_application_id`) REFERENCES `membership_applications`(`id`) ON DELETE RESTRICT,CONSTRAINT `memberships_type_foreign` FOREIGN KEY(`membership_type_id`) REFERENCES `membership_types`(`id`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `invoices` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`invoice_number` varchar(40) NOT NULL,`user_id` bigint unsigned NOT NULL,`membership_id` bigint unsigned NOT NULL,`membership_application_id` bigint unsigned NOT NULL,`currency` char(3) NOT NULL,`subtotal` decimal(12,2) NOT NULL,`total` decimal(12,2) NOT NULL,`amount_paid` decimal(12,2) NOT NULL DEFAULT 0,`balance_due` decimal(12,2) NOT NULL,`status` varchar(30) NOT NULL DEFAULT 'issued',`issued_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`due_at` timestamp NULL DEFAULT NULL,`paid_at` timestamp NULL DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `invoices_number_unique`(`invoice_number`),UNIQUE KEY `invoices_membership_unique`(`membership_id`),KEY `invoices_user_status_index`(`user_id`,`status`),KEY `invoices_application_index`(`membership_application_id`),KEY `invoices_issued_index`(`issued_at`),CONSTRAINT `invoices_user_foreign` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `invoices_membership_foreign` FOREIGN KEY(`membership_id`) REFERENCES `memberships`(`id`) ON DELETE RESTRICT,CONSTRAINT `invoices_application_foreign` FOREIGN KEY(`membership_application_id`) REFERENCES `membership_applications`(`id`) ON DELETE RESTRICT,CONSTRAINT `invoices_amounts_check` CHECK (`subtotal` >= 0 AND `total` >= 0 AND `amount_paid` >= 0 AND `balance_due` >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `invoice_items` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`invoice_id` bigint unsigned NOT NULL,`description` varchar(255) NOT NULL,`quantity` decimal(10,2) NOT NULL DEFAULT 1,`unit_amount` decimal(12,2) NOT NULL,`line_total` decimal(12,2) NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(`id`),KEY `invoice_items_invoice_index`(`invoice_id`),CONSTRAINT `invoice_items_invoice_foreign` FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`id`) ON DELETE RESTRICT,CONSTRAINT `invoice_items_amounts_check` CHECK (`quantity` > 0 AND `unit_amount` >= 0 AND `line_total` >= 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `payments` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`payment_reference` varchar(40) NOT NULL,`user_id` bigint unsigned NOT NULL,`amount` decimal(12,2) NOT NULL,`currency` char(3) NOT NULL,`payment_method` varchar(30) NOT NULL,`manual_reference` varchar(100) NOT NULL,`received_at` timestamp NOT NULL,`recorded_by` bigint unsigned NOT NULL,`status` varchar(30) NOT NULL DEFAULT 'completed',`note` varchar(1000) DEFAULT NULL,`reversal_of_payment_id` bigint unsigned DEFAULT NULL,`reversal_reason` varchar(1000) DEFAULT NULL,`idempotency_key` char(64) NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `payments_reference_unique`(`payment_reference`),UNIQUE KEY `payments_manual_reference_unique`(`manual_reference`),UNIQUE KEY `payments_idempotency_unique`(`idempotency_key`),UNIQUE KEY `payments_reversal_unique`(`reversal_of_payment_id`),KEY `payments_user_status_index`(`user_id`,`status`),KEY `payments_received_index`(`received_at`),CONSTRAINT `payments_user_foreign` FOREIGN KEY(`user_id`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `payments_recorder_foreign` FOREIGN KEY(`recorded_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `payments_reversal_foreign` FOREIGN KEY(`reversal_of_payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT,CONSTRAINT `payments_amount_check` CHECK (`amount` > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `payment_allocations` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`payment_id` bigint unsigned NOT NULL,`invoice_id` bigint unsigned NOT NULL,`amount` decimal(12,2) NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `payment_allocations_unique`(`payment_id`,`invoice_id`),KEY `payment_allocations_invoice_index`(`invoice_id`),CONSTRAINT `payment_allocations_payment_foreign` FOREIGN KEY(`payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT,CONSTRAINT `payment_allocations_invoice_foreign` FOREIGN KEY(`invoice_id`) REFERENCES `invoices`(`id`) ON DELETE RESTRICT,CONSTRAINT `payment_allocations_amount_check` CHECK (`amount` > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `refund_requests` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`request_reference` varchar(40) NOT NULL,`payment_id` bigint unsigned NOT NULL,`requested_by` bigint unsigned NOT NULL,`requested_amount` decimal(12,2) NOT NULL,`reason` varchar(1000) NOT NULL,`status` varchar(30) NOT NULL DEFAULT 'requested',`reviewed_by` bigint unsigned DEFAULT NULL,`reviewed_at` timestamp NULL DEFAULT NULL,`decision_reason` varchar(1000) DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,`updated_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `refund_requests_reference_unique`(`request_reference`),KEY `refund_requests_payment_status_index`(`payment_id`,`status`),KEY `refund_requests_requester_index`(`requested_by`,`created_at`),CONSTRAINT `refund_requests_payment_foreign` FOREIGN KEY(`payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT,CONSTRAINT `refund_requests_requester_foreign` FOREIGN KEY(`requested_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `refund_requests_reviewer_foreign` FOREIGN KEY(`reviewed_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `refund_requests_amount_check` CHECK (`requested_amount` > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `refunds` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`refund_reference` varchar(40) NOT NULL,`refund_request_id` bigint unsigned NOT NULL,`payment_id` bigint unsigned NOT NULL,`amount` decimal(12,2) NOT NULL,`method` varchar(30) NOT NULL,`processed_by` bigint unsigned NOT NULL,`processed_at` timestamp NOT NULL,`manual_reference` varchar(100) NOT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(`id`),UNIQUE KEY `refunds_reference_unique`(`refund_reference`),UNIQUE KEY `refunds_request_unique`(`refund_request_id`),UNIQUE KEY `refunds_manual_reference_unique`(`manual_reference`),KEY `refunds_payment_index`(`payment_id`),CONSTRAINT `refunds_request_foreign` FOREIGN KEY(`refund_request_id`) REFERENCES `refund_requests`(`id`) ON DELETE RESTRICT,CONSTRAINT `refunds_payment_foreign` FOREIGN KEY(`payment_id`) REFERENCES `payments`(`id`) ON DELETE RESTRICT,CONSTRAINT `refunds_processor_foreign` FOREIGN KEY(`processed_by`) REFERENCES `users`(`id`) ON DELETE RESTRICT,CONSTRAINT `refunds_amount_check` CHECK (`amount` > 0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE `finance_events` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`entity_type` varchar(50) NOT NULL,`entity_reference` varchar(40) NOT NULL,`actor_user_id` bigint unsigned DEFAULT NULL,`previous_status` varchar(40) DEFAULT NULL,`new_status` varchar(40) DEFAULT NULL,`action` varchar(80) NOT NULL,`note` varchar(1000) DEFAULT NULL,`created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(`id`),KEY `finance_events_entity_index`(`entity_type`,`entity_reference`,`created_at`),KEY `finance_events_actor_index`(`actor_user_id`,`created_at`),CONSTRAINT `finance_events_actor_foreign` FOREIGN KEY(`actor_user_id`) REFERENCES `users`(`id`) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
